package main

import (
	"bytes"
	"fmt"
	"os"
	"strings"

	"github.com/aperturerobotics/protobuf-go-lite/types/descriptorpb"
)

// luauLibrary is the handwritten part of the Luau library, which the
// generated module ends with.
const luauLibrary = "luau/library.luau"

// luauPreamble opens the generated module with the bridge, the vector types
// and the call every generated function makes.
const luauPreamble = `--!strict
-- Code generated by modlock-sdkgen from the schema and luau/library.luau.
-- DO NOT EDIT.

local wire = require("@self/wire")

-- host is the bridge the runtime hands the library.
local host = ...

local M = {}

-- schema describes every message the library encodes or decodes.
local schema: wire.Schema = {}

-- Vector is a position or direction in the world, in game units.
export type Vector = { x: number, y: number, z: number }

-- Angles is a rotation in degrees.
export type Angles = { pitch: number, yaw: number, roll: number }

-- call calls one Host method with its request and returns the decoded
-- response, true when the method answers nothing, or nil when the call
-- failed; the host logs why.
local function call(method: string, requestType: string, request: any, responseType: string?): any
	local encoded = wire.encode(schema, "Call", {
		method = method,
		request = wire.encode(schema, requestType, request),
	})
	local reply = wire.decode(schema, "Reply", host.hostCall(encoded))
	if reply.error ~= "" then
		return nil
	end
	if responseType == nil then
		return true
	end
	return wire.decode(schema, responseType, reply.response)
end

-- with returns a copy of options that holds value under name.
local function with(options: any, name: string, value: any): any
	local request = table.clone(options)
	request[name] = value
	return request
end

`

// luauWriter writes the Luau library's module.
type luauWriter struct {
	*directions
	s     *schema
	out   bytes.Buffer
	calls []*call
	// absent holds the result field of each call that answers nil when the
	// host leaves it out.
	absent map[*field]bool
}

// writeLuau returns luau/modlock/init.luau, which ends with the handwritten
// luau/library.luau.
func writeLuau(s *schema) ([]byte, error) {
	calls, err := s.calls()
	if err != nil {
		return nil, err
	}
	library, err := os.ReadFile(luauLibrary)
	if err != nil {
		return nil, err
	}
	w := &luauWriter{directions: s.directions(calls), s: s, calls: calls, absent: map[*field]bool{}}
	for _, c := range calls {
		if f := c.result; f != nil && f.message != nil && !f.repeated && !f.message.isUnion() {
			w.absent[f] = true
		}
	}
	w.out.WriteString(luauPreamble)
	if err := w.writeTypes(); err != nil {
		return nil, err
	}
	for _, c := range classes {
		w.writeClass(c)
	}
	if err := w.writeSchema(); err != nil {
		return nil, err
	}
	for _, c := range calls {
		if c.class == nil {
			w.writeCall(c)
		}
	}
	w.writeMod()
	w.out.Write(library)
	return w.out.Bytes(), nil
}

// writeTypes writes the enums, with their tables, and the message types in
// schema order.
func (w *luauWriter) writeTypes() error {
	for _, e := range w.s.enumOrder {
		if !w.enumsIn[e] && !w.enumsOut[e] {
			continue
		}
		writeLuauDoc(&w.out, "", e.doc)
		var names, entries []string
		for _, v := range e.named() {
			names = append(names, fmt.Sprintf("%q", e.valueName(v)))
			entries = append(entries, fmt.Sprintf("\t[%d] = %q,\n\t%s = %d,\n", v.number, e.valueName(v), e.valueName(v), v.number))
		}
		fmt.Fprintf(&w.out, "export type %s = %s\n", e.name, strings.Join(names, " | "))
		fmt.Fprintf(&w.out, "local %s: { [any]: any } = {\n%s}\n\n", e.name, strings.Join(entries, ""))
	}
	for _, m := range w.s.messageOrder {
		if mapped(m) != "" || (!w.inputs[m] && !w.outputs[m]) {
			continue
		}
		writeLuauDoc(&w.out, "", m.doc)
		if m.isUnion() {
			fmt.Fprintf(&w.out, "export type %s = %s\n\n", m.name, w.oneofType(m.oneofs[0]))
			continue
		}
		outputOnly := w.outputs[m] && !w.inputs[m]
		fmt.Fprintf(&w.out, "export type %s = {\n", m.name)
		for _, f := range m.fields {
			if f == w.omitted[m] {
				continue
			}
			if o := f.oneof; o != nil {
				if o.fields[0] == f {
					writeLuauDoc(&w.out, "\t", fieldDoc(m, rename(o.doc, camel(o.name), lowerCamel(o.name))))
					fmt.Fprintf(&w.out, "\t%s: (%s)?,\n", luauKey(lowerCamel(o.name)), w.oneofType(o))
				}
				continue
			}
			mark := ""
			if f.optional || (f.repeated && !outputOnly) || (f.enum != nil && !f.repeated && w.outputs[m]) {
				mark = "?"
			}
			writeLuauDoc(&w.out, "\t", fieldDoc(m, f.doc))
			fmt.Fprintf(&w.out, "\t%s: %s%s,\n", luauKey(lowerCamel(f.name)), luauType(f), mark)
		}
		w.out.WriteString("}\n\n")
	}
	return nil
}

// oneofType returns the union of the types of o's cases. The encoder finds
// the case of a value by its typeof, taking the first case that matches, so
// a later case of the same Luau type, such as an int64 after a double, only
// decodes.
func (w *luauWriter) oneofType(o *oneof) string {
	seen := map[string]bool{}
	var types []string
	for _, f := range o.fields {
		if t := luauBase(f); !seen[t] {
			seen[t] = true
			types = append(types, t)
		}
	}
	return strings.Join(types, " | ")
}

// writeClass writes one class: its type, which lists its methods, its
// constructor and its calls as methods.
func (w *luauWriter) writeClass(c *class) {
	writeLuauDoc(&w.out, "", c.doc)
	fmt.Fprintf(&w.out, "export type %s = {\n", c.name)
	writeLuauDoc(&w.out, "\t", c.keyDoc)
	fmt.Fprintf(&w.out, "\t%s: number,\n", c.key)
	for _, call := range w.calls {
		if call.class == c {
			writeLuauDoc(&w.out, "\t", rename(call.method.doc, call.method.name, call.name))
			params := append([]string{"self: " + c.name}, w.params(call)...)
			result, _ := w.resultType(call)
			fmt.Fprintf(&w.out, "\t%s: (%s) -> %s,\n", call.name, strings.Join(params, ", "), result)
		}
	}
	w.out.WriteString("}\n")
	fmt.Fprintf(&w.out, "local %s = {}\n%s.__index = %s\n\n", c.name, c.name, c.name)
	fmt.Fprintf(&w.out, "-- new returns the %s with %s.\n", c.name, c.key)
	fmt.Fprintf(&w.out, "function %s.new(%s: number): %s\n", c.name, c.key, c.name)
	fmt.Fprintf(&w.out, "\treturn setmetatable({ %s = %s }, %s) :: any\nend\n\n", c.key, c.key, c.name)
	for _, call := range w.calls {
		if call.class == c {
			w.writeCall(call)
		}
	}
	fmt.Fprintf(&w.out, "M.%s = %s\n\n", c.name, c.name)
}

// params returns the declared parameters of c, without its receiver.
func (w *luauWriter) params(c *call) []string {
	if c.options {
		return []string{"options: " + c.method.request.name}
	}
	var params []string
	for _, p := range c.params {
		mark := ""
		if p.optional {
			mark = "?"
		}
		var t string
		if p.oneof != nil {
			t = "(" + w.oneofType(p.oneof) + ")"
		} else {
			t = luauType(p.field)
		}
		params = append(params, fmt.Sprintf("%s: %s%s", luauLocal(p.name), t, mark))
	}
	return params
}

// resultType returns the type a call returns and the value it returns when
// the call fails.
func (w *luauWriter) resultType(c *call) (string, string) {
	f := c.result
	switch {
	case f == nil:
		return "boolean", "false"
	case f.repeated:
		return luauType(f), "{}"
	case f.kind == descriptorpb.FieldDescriptorProto_TYPE_BOOL && !f.optional:
		return "boolean", "false"
	}
	return luauBase(f) + "?", "nil"
}

// writeCall writes one call as a method of its class, or else as a function
// of the module.
func (w *luauWriter) writeCall(c *call) {
	params := w.params(c)
	owner := "M"
	if c.class != nil {
		owner = c.class.name
		params = append([]string{"self: " + c.class.name}, params...)
	}
	result, failure := w.resultType(c)
	writeLuauDoc(&w.out, "", rename(c.method.doc, c.method.name, c.name))
	fmt.Fprintf(&w.out, "function %s.%s(%s): %s\n", owner, c.name, strings.Join(params, ", "), result)

	// Build the request.
	var request string
	switch {
	case c.options && c.receiver != nil:
		request = fmt.Sprintf("with(options, %q, self)", lowerCamel(c.receiver.name))
	case c.options:
		request = "options"
	default:
		var members []string
		if c.receiver != nil {
			members = append(members, lowerCamel(c.receiver.name)+" = self")
		}
		for _, p := range c.params {
			members = append(members, luauKey(p.name)+" = "+luauLocal(p.name))
		}
		request = "{}"
		if len(members) != 0 {
			request = "{ " + strings.Join(members, ", ") + " }"
		}
	}
	send := fmt.Sprintf("call(%q, %q, %s", c.method.name, c.method.request.name, request)
	if c.result == nil {
		fmt.Fprintf(&w.out, "\treturn %s) ~= nil\nend\n\n", send)
		return
	}
	fmt.Fprintf(&w.out, "\tlocal response = %s, %q)\n", send, c.method.response.name)
	fmt.Fprintf(&w.out, "\tif response == nil then\n\t\treturn %s\n\tend\n", failure)
	fmt.Fprintf(&w.out, "\treturn response%s\nend\n\n", luauIndex(lowerCamel(c.result.name)))
}

// writeSchema writes the descriptor of every message the library encodes or
// decodes.
func (w *luauWriter) writeSchema() error {
	var r reach
	for _, m := range w.s.messageOrder {
		if m.name == "Call" || m.name == "Reply" || m.name == "Empty" {
			r.add(m)
		}
	}
	for _, c := range w.calls {
		r.add(c.method.request)
		r.add(c.method.response)
	}
	for _, m := range w.s.mod.methods {
		r.add(m.request)
		r.add(m.response)
	}
	for _, m := range w.s.messageOrder {
		if !r.seen[m] {
			continue
		}
		if len(m.fields) == 0 {
			fmt.Fprintf(&w.out, "schema.%s = {}\n", m.name)
			continue
		}
		fmt.Fprintf(&w.out, "schema.%s = {\n", m.name)
		for _, f := range m.fields {
			descriptor, err := w.descriptor(f)
			if err != nil {
				return fmt.Errorf("%s: %w", m.name, err)
			}
			fmt.Fprintf(&w.out, "\t{ %s },\n", descriptor)
		}
		w.out.WriteString("}\n")
	}
	w.out.WriteString("\n")
	return nil
}

// luauKinds holds the name the codec gives each protobuf type it encodes.
var luauKinds = map[descriptorpb.FieldDescriptorProto_Type]string{
	descriptorpb.FieldDescriptorProto_TYPE_DOUBLE:  "double",
	descriptorpb.FieldDescriptorProto_TYPE_FLOAT:   "float",
	descriptorpb.FieldDescriptorProto_TYPE_INT64:   "int64",
	descriptorpb.FieldDescriptorProto_TYPE_UINT64:  "uint64",
	descriptorpb.FieldDescriptorProto_TYPE_INT32:   "int32",
	descriptorpb.FieldDescriptorProto_TYPE_FIXED32: "fixed32",
	descriptorpb.FieldDescriptorProto_TYPE_BOOL:    "bool",
	descriptorpb.FieldDescriptorProto_TYPE_STRING:  "string",
	descriptorpb.FieldDescriptorProto_TYPE_MESSAGE: "message",
	descriptorpb.FieldDescriptorProto_TYPE_BYTES:   "bytes",
	descriptorpb.FieldDescriptorProto_TYPE_UINT32:  "uint32",
	descriptorpb.FieldDescriptorProto_TYPE_ENUM:    "enum",
}

// descriptor returns the members of f's descriptor.
func (w *luauWriter) descriptor(f *field) (string, error) {
	kind, ok := luauKinds[f.kind]
	if !ok {
		return "", fmt.Errorf("the Luau codec has no %s for %s", f.kind, f.name)
	}
	members := []string{
		fmt.Sprintf("number = %d", f.number),
		fmt.Sprintf("name = %q", lowerCamel(f.name)),
		fmt.Sprintf("kind = %q", kind),
	}
	switch {
	case f.repeated:
		members = append(members, "repeated = true")
	case f.optional || w.absent[f]:
		members = append(members, "optional = true")
	}
	if f.oneof != nil {
		members = append(members, fmt.Sprintf("oneof = %q", lowerCamel(f.oneof.name)))
	}
	if f.message != nil {
		members = append(members, fmt.Sprintf("message = %q", f.message.name))
		if f.message.isUnion() {
			members = append(members, fmt.Sprintf("union = %q", lowerCamel(f.message.oneofs[0].name)))
		}
	}
	if f.enum != nil {
		members = append(members, "enum = "+f.enum.name)
	}
	if c := classOf(f); c != nil {
		members = append(members, "class = "+c.name, fmt.Sprintf("key = %q", c.key))
	}
	if isID(f) {
		members = append(members, "id = true")
	}
	return strings.Join(members, ", "), nil
}

// writeMod writes the type of the mod's event handlers and the dispatch that
// runs them.
func (w *luauWriter) writeMod() {
	writeLuauDoc(&w.out, "", "ModHandlers handles the events the game delivers to the mod.")
	w.out.WriteString("export type ModHandlers = {\n")
	for _, m := range w.s.mod.methods {
		writeLuauDoc(&w.out, "\t", rename(m.doc, m.name, lowerCamel(m.name)))
		param := ""
		if !m.request.isEmpty() {
			param = "event: " + m.request.name
		}
		result := "()"
		if !m.response.isEmpty() {
			result = m.response.name
		}
		fmt.Fprintf(&w.out, "\t%s: (%s) -> %s,\n", lowerCamel(m.name), param, result)
	}
	w.out.WriteString("}\n\n")

	w.out.WriteString("-- events holds each Mod method's request, response and handler.\n")
	w.out.WriteString("local events: { [string]: { request: string, response: string, handler: string } } = {\n")
	for _, m := range w.s.mod.methods {
		fmt.Fprintf(&w.out, "\t%s = { request = %q, response = %q, handler = %q },\n",
			m.name, m.request.name, m.response.name, lowerCamel(m.name))
	}
	w.out.WriteString("}\n\n")
	w.out.WriteString(`-- serveMod runs the encoded Call in bytes on handlers and returns the encoded
-- Reply. A handler that errors answers with its error and traceback.
local function serveMod(handlers: ModHandlers, bytes: string): string
	local request = wire.decode(schema, "Call", bytes)
	local event = events[request.method]
	if event == nil then
		return wire.encode(schema, "Reply", { error = "the mod has no method " .. request.method })
	end
	local handler = (handlers :: any)[event.handler]
	local ok, response = xpcall(function()
		local answer = handler(wire.decode(schema, event.request, request.request))
		return wire.encode(schema, event.response, answer or {})
	end, function(message: any): string
		return debug.traceback(tostring(message), 2)
	end)
	if not ok then
		return wire.encode(schema, "Reply", { error = tostring(response) })
	end
	return wire.encode(schema, "Reply", { response = response })
end

`)
}

// luauType returns the Luau type of a field, repeated or not.
func luauType(f *field) string {
	if f.repeated {
		return "{ " + luauBase(f) + " }"
	}
	return luauBase(f)
}

// luauBase returns the Luau type of one value of a field.
func luauBase(f *field) string {
	if c := classOf(f); c != nil {
		return c.name
	}
	switch {
	case f.message != nil:
		if name := mapped(f.message); name != "" {
			return name
		}
		return f.message.name
	case f.enum != nil:
		return f.enum.name
	case f.kind == descriptorpb.FieldDescriptorProto_TYPE_BOOL:
		return "boolean"
	case f.kind == descriptorpb.FieldDescriptorProto_TYPE_STRING, f.kind == descriptorpb.FieldDescriptorProto_TYPE_BYTES, isID(f):
		return "string"
	}
	return "number"
}

// luauKeywords are the reserved words of Luau, which a field name cannot
// use as a plain name.
var luauKeywords = set(strings.Fields(`and break do else elseif end false for function if in
	local nil not or repeat return then true until while`))

// luauKey returns name as a key of a table type or constructor.
func luauKey(name string) string {
	if luauKeywords[name] {
		return fmt.Sprintf("[%q]", name)
	}
	return name
}

// luauIndex returns the expression suffix that indexes a table by name.
func luauIndex(name string) string {
	if luauKeywords[name] {
		return fmt.Sprintf("[%q]", name)
	}
	return "." + name
}

// luauLocal returns name as a local variable or parameter.
func luauLocal(name string) string {
	if luauKeywords[name] {
		return name + "_"
	}
	return name
}

// isID reports whether f is a 64-bit id, which the Luau library holds as a
// decimal string because a number cannot hold every id exactly.
func isID(f *field) bool {
	return is64(f) && strings.HasSuffix(f.name, "_id")
}

// writeLuauDoc writes text as a comment at indent.
func writeLuauDoc(out *bytes.Buffer, indent, text string) {
	if text == "" {
		return
	}
	for _, line := range strings.Split(text, "\n") {
		if line == "" {
			fmt.Fprintf(out, "%s--\n", indent)
			continue
		}
		fmt.Fprintf(out, "%s-- %s\n", indent, line)
	}
}
